from collections import deque

def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); cells=[]
    while q:
     a,b=q.pop(); cells.append((a,b))
     for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
      if 0<=x<h and 0<=y<w and grid[x][y] and (x,y) not in seen:
       seen.add((x,y));q.append((x,y))
    out.append(cells)
 return out
